select 'B Büros veröffentlicht (erwartet 3)', count(*)::text, '' from public.directory_listings where slug in ('leptos-estates', 'armonia-estates-ltd-12525', 'leptos-estates-limassol') and status = 'published'
union all
select 'C neue Konzernzeilen veröffentlicht (erwartet 4)', count(*)::text, '' from public.directory_listings where slug in ('leptos-vesta-holidays', 'leptos-chestertons-cyprus', 'leptos-resitour-holiday-residences', 'leptos-arena-sports') and status = 'published'
union all
select 'D fehlende neue Zeilen (erwartet: keine; sonst wurde sie wegen einer Dublette übersprungen)', coalesce(string_agg(s.slug, ', '), 'keine'), ''
  from unnest(array['leptos-estates-limassol', 'leptos-vesta-holidays', 'leptos-chestertons-cyprus', 'leptos-resitour-holiday-residences', 'leptos-arena-sports', 'leptos-estates-adonis-beach-villas', 'leptos-estates-akakia-villas', 'leptos-estates-akamantis-gardens', 'leptos-estates-akropolis-275', 'leptos-estates-aphrodite-springs', 'leptos-estates-apollo-beach-villas', 'leptos-estates-argaka-beach-villas', 'leptos-estates-armonia-beach-villas', 'leptos-estates-belvedere-villas', 'leptos-estates-coral-bay-villas', 'leptos-estates-coral-gardens', 'leptos-estates-coral-seas-villas', 'leptos-estates-eden-beach-apartments', 'leptos-estates-fortuna-court-i', 'leptos-estates-iasonas-beach-villas', 'leptos-estates-kamares-village', 'leptos-estates-kings-court', 'leptos-estates-kings-gardens', 'leptos-estates-latchi-beach-villas', 'leptos-estates-limassol-blu-marine', 'leptos-estates-limassol-park', 'leptos-estates-limnaria-gardens', 'leptos-estates-mandria-gardens', 'leptos-estates-maniki-beach-villas', 'leptos-estates-neapolis-smart-ecocity', 'leptos-estates-olympus-village', 'leptos-estates-paphos-gardens', 'leptos-estates-paradise-gardens', 'leptos-estates-perneri-villas', 'leptos-estates-peyia-gardens', 'leptos-estates-peyia-hills-apartments', 'leptos-estates-pissouri-villas', 'leptos-estates-polis-beach-villas', 'leptos-estates-regina-gardens', 'leptos-estates-sea-caves-villas', 'leptos-estates-venus-gardens-resort', 'leptos-estates-vikla-villas', 'leptos-estates-west-park-court', 'leptos-estates-zanatzia-plots-villas', 'leptos-estates-zelemenos-village']) as s(slug)
