select 'E ' || type || ' / ' || status, slug, coalesce(district, '-') || ' / ' || coalesce(coords_precision, '-') || ' / ' || round(lat::numeric, 4)::text || ',' || round(lng::numeric, 4)::text || ' / Bild: ' || (image is not null)::text
